head.b:skin:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #F2F2F7;     /* iOS Light Background */
  --glass: rgba(255, 255, 255, 0.7);
  --glass2: rgba(255, 255, 255, 0.5);
  --border: rgba(0, 0, 0, 0.1);
  --teal: #007AFF;   /* iOS Light Blue */
  --green: #34C759;  /* iOS Light Green */
  --red: #FF3B30;    /* iOS Light Red */
  --amber: #FF9500;  /* iOS Light Orange */
  --text: #000000;
  --muted: rgba(60, 60, 67, 0.6);
  --radius: 32px;    /* iOS Widget Radius */
}

body {
  margin: 0; padding: 0;
  background-color: var(--bg);
  background-image: radial-gradient(circle at 10% 20%, rgba(0, 122, 255, 0.08) 0%, transparent 40%),
                    radial-gradient(circle at 90% 80%, rgba(52, 199, 89, 0.08) 0%, transparent 40%);
  background-attachment: fixed;
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--text);
  text-align: center;
  direction: ltr;
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%; text-size-adjust: 100%;
  touch-action: manipulation;
  overscroll-behavior: none;
}

.container { padding: 24px; max-width: 860px; margin: auto; padding-bottom: 70px; }

.box {
  background: var(--glass);
  backdrop-filter: blur(40px) saturate(200%); -webkit-backdrop-filter: blur(40px) saturate(200%);
  border: 1px solid var(--border);
  padding: 32px 24px;
  border-radius: var(--radius);
  box-shadow: 0 10px 40px rgba(0,0,0,0.06);
  margin-top: 36px;
}

h2 { margin-bottom: 16px; font-size: 24px; font-weight: 700; letter-spacing: -0.5px; }
h3 { font-weight: 600; letter-spacing: -0.3px; }
p  { color: var(--muted); font-size: 15px; line-height: 1.5; font-weight: 400; }

.screen { display: none; }
.active-screen { display: block; animation: scaleIn .4s cubic-bezier(0.25, 0.8, 0.25, 1); }
@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.97) translateY(10px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

/* ── BUTTONS (iOS Style) ── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 14px 24px; border: none; border-radius: 18px;
  font-size: 16px; cursor: pointer; font-weight: 600; letter-spacing: -0.3px;
  margin: 6px; color: #fff; transition: all .2s ease;
}
.btn:active { transform: scale(0.95); opacity: 0.8; }
.btn-admin  { background: var(--teal); }
.btn-driver { background: rgba(0, 0, 0, 0.05); color: var(--teal); border: 1px solid rgba(0,0,0,0.05); }
.btn-success{ background: var(--green); color: #fff; }
.btn-back   { background: transparent; color: var(--teal); }
.btn-danger { background: var(--red); }
.btn-install{ background: var(--amber); color: #fff; animation: pulse 2s infinite; }
.btn-notif  { background: var(--teal); }
.btn-sm     { padding: 8px 16px; font-size: 14px; margin: 4px; border-radius: 14px; }
.btn:disabled { cursor: not-allowed; opacity: 0.5; }

@keyframes pulse {
  0%,100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(255, 149, 0, .4); }
  50%      { transform: scale(1.02); box-shadow: 0 0 0 10px rgba(255, 149, 0, 0); }
}

/* ── INPUTS (iOS Search Bar Style) ── */
.input-field {
  padding: 14px 16px; width: 85%; max-width: 320px;
  background: rgba(118, 118, 128, 0.12);
  border: none; border-radius: 14px;
  font-size: 17px; margin-bottom: 16px; outline: none;
  text-align: center; display: block; margin-left: auto; margin-right: auto;
  color: #000;
  transition: background .2s, box-shadow .2s;
}
.input-field::placeholder { color: rgba(60, 60, 67, 0.4); }
.input-field:focus { background: rgba(118, 118, 128, 0.18); box-shadow: 0 0 0 2px var(--teal); }

.alert-msg { color: var(--red); font-size: 14px; margin-top: 10px; display: none; font-weight: 500; }

/* ── LIVE LOCATION TRACKER (iOS Widget Style) ── */
#liveTracker {
  width: 100%; max-width: 340px; margin: 20px auto;
  border-radius: 28px;
  padding: 24px 16px; text-align: center;
  background: rgba(255, 255, 255, 0.5);
  border: 1px solid var(--border);
  box-shadow: 0 4px 15px rgba(0,0,0,0.03);
  transition: all .4s cubic-bezier(0.25, 0.8, 0.25, 1);
}
#liveTracker.in-range  { background: rgba(52, 199, 89, 0.1); border-color: rgba(52, 199, 89, 0.3); }
#liveTracker.out-range { background: rgba(255, 149, 0, 0.1); border-color: rgba(255, 149, 0, 0.3); }
#liveTracker .lt-label    { font-size: 13px; color: var(--muted); font-weight: 600; text-transform: uppercase; }
#liveTracker .lt-distance { font-size: 40px; font-weight: 700; color: #000; margin: 8px 0; letter-spacing: -1px; }
#liveTracker.in-range .lt-distance { color: var(--green); }
#liveTracker .lt-state    { font-size: 14px; font-weight: 500; color: var(--muted); }

/* ── SYSTEM ON/OFF SWITCH (iOS Toggle Style) ── */
.system-switch {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 20px; border-radius: 20px;
  margin: 8px 0 20px; background: var(--glass2); border: 1px solid var(--border);
  transition: all .3s ease;
}
.system-switch .ssw-info { display: flex; align-items: center; gap: 12px; font-weight: 600; font-size: 16px; color: #000; }
.system-switch .ssw-dot { width: 10px; height: 10px; border-radius: 50%; }
.system-switch.sys-on  .ssw-dot { background: var(--green); box-shadow: 0 0 8px var(--green); }
.system-switch.sys-off .ssw-dot { background: var(--red); box-shadow: 0 0 8px var(--red); }
.system-switch.sys-on  #sswBtn { background: rgba(255, 59, 48, 0.15); color: var(--red); border-radius: 20px; }
.system-switch.sys-off #sswBtn { background: rgba(52, 199, 89, 0.15); color: var(--green); border-radius: 20px; }

/* ── QUEUE STATUS BOX ── */
.queue-status-box {
  background: transparent;
  padding: 20px 16px; border-radius: 24px;
  margin: 16px auto 24px; font-size: 18px; font-weight: 600;
  transition: all .4s ease; max-width: 320px; color: #000;
}
.queue-status-box .big-number {
  font-size: clamp(48px, 16vw, 84px); display: block;
  margin: 4px 0; color: #000; font-weight: 800; letter-spacing: -2px;
  text-shadow: 0 4px 20px rgba(0,0,0,0.1);
  line-height: 1; word-break: break-all;
}

/* ── PUSH PERMISSION BOX ── */
.push-permission-box {
  background: rgba(0, 0, 0, 0.02); border: 1px solid var(--border);
  border-radius: 20px; padding: 20px; margin: 16px auto; max-width: 340px;
}
.push-permission-box p { color: var(--muted); font-size: 14px; margin-bottom: 12px; }

/* ── PUSH STATUS INDICATOR ── */
.push-status {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 13px; font-weight: 600; padding: 6px 14px; border-radius: 30px;
  background: rgba(0,0,0,0.05); border: 1px solid var(--border);
  margin-bottom: 12px; color: #000;
}
.push-dot { width: 8px; height: 8px; border-radius: 50%; }
.push-dot.on  { background: var(--green); box-shadow: 0 0 8px var(--green); }
.push-dot.off { background: var(--red); }
.push-dot.loading { background: var(--amber); animation: blink 1.5s infinite ease-in-out; }
@keyframes blink { 0%,100%{opacity:1;} 50%{opacity:.4;} }

/* ── DASHBOARDS ── */
.next-driver-box {
  background: rgba(52, 199, 89, 0.1); border: 1px solid rgba(52, 199, 89, 0.2);
  padding: 24px; border-radius: 24px; margin-bottom: 24px;
}
.next-driver-box h3 { color: var(--green); margin: 0 0 8px; font-size: 15px; text-transform: uppercase; }
.next-driver-box h2 { color: #000; margin: 8px 0; font-size: 24px; font-weight: 700; }

/* ── TABLES (iOS List Style) ── */
.queue-table { width: 100%; border-collapse: separate; border-spacing: 0; margin-top: 16px; text-align: center; border-radius: 16px; overflow: hidden; background: var(--glass2); }
.queue-table th { background: rgba(0,0,0,0.03); color: var(--muted); padding: 14px 10px; font-size: 13px; font-weight: 600; text-transform: uppercase; }
.queue-table td { padding: 14px 10px; font-size: 15px; border-bottom: 1px solid var(--border); color: #000; }
.queue-table tr:last-child td { border-bottom: none; }
.queue-table tr:first-child td { background: rgba(52, 199, 89, 0.1); color: var(--green); font-weight: 600; }
.history-table th { background: rgba(0,0,0,0.02); }
.history-table tr:first-child td { background: transparent; color: #000; font-weight: normal; }

.stats-row { display: flex; gap: 12px; margin-bottom: 24px; flex-wrap: wrap; justify-content: space-between;}
.stat-card { flex: 1; min-width: 80px; background: var(--glass2); border-radius: 20px; padding: 16px 10px; border: 1px solid var(--border); }
.stat-num   { font-size: 28px; font-weight: 700; color: #000; }
.stat-label { font-size: 12px; color: var(--muted); font-weight: 500; margin-top: 4px; }

.btn-remove { background: rgba(255, 59, 48, 0.1); color: var(--red); border: none; padding: 6px 14px; border-radius: 12px; cursor: pointer; font-size: 13px; font-weight: 600; }
.btn-remove:hover { background: rgba(255, 59, 48, 0.2); }

.admin-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; flex-wrap: wrap; gap: 12px; color: #000; }

/* ── SIDEBAR (iOS Blur Panel) ── */
.admin-sidebar {
  position: fixed; top: 0; right: -320px; width: 320px; height: 100vh;
  background: rgba(242, 242, 247, 0.85); backdrop-filter: blur(50px) saturate(200%); -webkit-backdrop-filter: blur(50px) saturate(200%);
  border-left: 1px solid var(--border); z-index: 10000; padding: 24px;
  transition: right .4s cubic-bezier(0.25, 0.8, 0.25, 1); overflow-y: auto; text-align: left;
}
.admin-sidebar.open { right: 0; }
.admin-sidebar h3 { color: var(--amber); padding-bottom: 16px; margin-top: 24px; font-size: 17px; font-weight: 600; }
.close-sidebar-btn { position: absolute; top: 16px; right: 20px; background: rgba(0,0,0,0.05); border: none; border-radius: 50%; width: 32px; height: 32px; color: #000; font-size: 16px; cursor: pointer; display:flex; align-items:center; justify-content:center; }
.unscanned-list { list-style: none; padding: 0; background: rgba(255,255,255,0.6); border-radius: 16px; overflow: hidden; }
.unscanned-list li { padding: 14px 16px; border-bottom: 1px solid var(--border); font-size: 15px; display: flex; justify-content: space-between; color: #000; }
.unscanned-list li:last-child { border-bottom: none; }
.unscanned-badge { background: var(--amber); color: #fff; border-radius: 12px; padding: 2px 10px; font-size: 12px; font-weight: 700; }

/* ── NOTIFICATIONS (Dynamic Island Style - always black on iOS) ── */
#notif-banner {
  position: fixed; top: 16px; left: 50%; transform: translateX(-50%) translateY(-100px) scale(0.9);
  background: #000000; color: #ffffff;
  padding: 14px 24px; border-radius: 40px;
  font-size: 15px; font-weight: 600; letter-spacing: -0.2px;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.05), 0 10px 40px rgba(0,0,0,0.2);
  z-index: 9999;
  transition: all .5s cubic-bezier(0.34, 1.56, 0.64, 1);
  white-space: nowrap; max-width: 90vw; text-overflow: ellipsis; overflow: hidden;
  display: flex; align-items: center; gap: 8px;
}
#notif-banner.show { transform: translateX(-50%) translateY(0) scale(1); }

#toast-wrap { position: fixed; bottom: 32px; left: 50%; transform: translateX(-50%); z-index: 9998; display: flex; flex-direction: column; gap: 10px; align-items: center; }

/* ── HIDE BLOGGER DEFAULT UI ON ALL DEVICES ── */
.blog-posts, .post-outer, .date-outer, #blog-pager, .blog-feeds,
.mobile-post-outer, .mobile-index-contents, .mobile-link-button,
.mobile-desktop-link, .Attribution, #main, .main, footer, #footer,
#header, .header, .mobile-header, .Header, h1.title, .titlewrapper {
  display: none !important;
}

body.script:
    //

    /* ═══════════════════════════════════════════════════════
       ▶ CONFIGURATION
       ═══════════════════════════════════════════════════════ */

    var ONESIGNAL_APP_ID = 'YOUR-ONESIGNAL-APP-ID-HERE';
    var ADMIN_PASSWORD = '733';
    var ONESIGNAL_REST_KEY = 'YOUR-ONESIGNAL-REST-API-KEY-HERE';

    var TOPIC_SYNC     = 'qs_sync_mandoobs_wh_8891';
    var TOPIC_STATE    = 'qs_state_mandoobs_wh_8891';
    var TOPIC_PRESENCE = 'qs_presence_mandoobs_wh_8891';

// ── GPS auto-queue ────────────────────────────────────────────────────
    var TARGET_LAT        = 24.7993316;    // warehouse latitude
    var TARGET_LNG        = 46.7590946;    // warehouse longitude
    var AUTO_JOIN_METERS  = 100;          // ≤ this → auto-join queue
    var AUTO_LEAVE_METERS = 130;          // > this → auto-leave (buffer avoids GPS jitter)
    /* ═══════════════════════════════════════════════════════
       STATE & STORAGE
       ═══════════════════════════════════════════════════════ */
    function sg(k,fb){ try{var v=localStorage.getItem(k);return v!==null?JSON.parse(v):fb;}catch(e){return fb;} }
    function ss(k,v) { try{localStorage.setItem(k,JSON.stringify(v));}catch(e){} }

    var AUTHORIZED_DRIVERS = {};
    var isAdmin       = false;
    var currentDriver = { id: null, name: null };
    var geoWatchId    = null;     // navigator.geolocation.watchPosition handle
    var prevMyPos     = -1;       // rep's position on last cloud update (for #1 detection)
    var servedCooldown = false;   // block auto-rejoin after being served for 5 min at location
    var servedAt      = 0;        // timestamp when cooldown started (Date.now())
    var lastDist      = 9999;     // last known distance in metres (for countdown refresh)
    var systemActive  = true;     // master on/off (synced via cloud)
    var wakeLock      = null;      // Screen Wake Lock — keeps GPS alive while app is open/backgrounded
    var ringInterval  = null, ringCount = 0;
    var mqttClient    = null;
    var myOSPlayerId  = null;
    var onlineReps    = {};       // Stores dynamic active connection pings

    // Unique Device Tracking for login prevention
    var myDeviceId  = sg('my_device_id', Math.random().toString(36).substr(2,9));
    ss('my_device_id', myDeviceId);
    var loginTimeout = null;

    // Load initial state from local storage
    var queue        = sg('sys_queue',   []);
    var historyLog   = sg('sys_history', []);
    systemActive     = sg('sys_active',  true);

    // ── SERVED COOLDOWN PERSISTENCE ──
    // The post-serve wait (5 min) must survive a page refresh / reopen, otherwise
    // the rep would get a new number immediately after reloading. We persist the
    // moment the cooldown started (per rep) and restore it on load.
    function beginServedCooldown(){
      servedCooldown = true; servedAt = Date.now();
      if(currentDriver && currentDriver.id) ss('served_at_' + currentDriver.id, servedAt);
    }
    function clearServedCooldown(){
      servedCooldown = false; servedAt = 0;
      if(currentDriver && currentDriver.id) ss('served_at_' + currentDriver.id, 0);
    }
    function restoreServedCooldown(){
      if(!currentDriver || !currentDriver.id){ servedCooldown = false; servedAt = 0; return; }
      var sa = sg('served_at_' + currentDriver.id, 0);
      if(sa && (Date.now() - sa) < 300000){ servedCooldown = true; servedAt = sa; }
      else { servedCooldown = false; servedAt = 0; ss('served_at_' + currentDriver.id, 0); }
    }

    /* ═══════════════════════════════════════════════════════
       BREAK SYSTEM FUNCTIONS
       ═══════════════════════════════════════════════════════ */
    function getRemainingBreakTime() {
      if(!currentDriver || !currentDriver.id) return 0;
      var breakUntil = sg('break_until_' + currentDriver.id, 0);
      var now = Date.now();
      return (now < breakUntil) ? (breakUntil - now) : 0;
    }

    function giveBreak(id) {
      if(!confirm('إعطاء المندوب بريك لمدة ساعة؟ سيتم إخراجه من الطابور.')) return;

      if(mqttClient && mqttClient.connected) {
        mqttClient.publish(TOPIC_SYNC, JSON.stringify({
          command: 'FORCE_BREAK',
          id: String(id),
          duration: 3600000
        }), { qos: 1 });
      }

      var idx = queue.findIndex(function(d){ return String(d.id) === String(id); });
      if(idx !== -1) {
        var wasFirst = (idx === 0);
        var removedName = queue[idx].name;
        queue.splice(idx, 1);
        ss('sys_queue', queue);
        renderAdminUI();
        syncStateToCloud();
        showToast('☕ تم إخراج ' + removedName + ' لفترة راحة لمدة ساعة', '#FF9500');

        if(wasFirst && queue.length > 0 && queue[0].osPlayerId) {
          sendPushToNewFirst(queue[0].osPlayerId, queue[0].name);
        }
      }
    }

    /* ═══════════════════════════════════════════════════════
       BLOGGER FEED
       ═══════════════════════════════════════════════════════ */
    function loadDrivers() {
      fetch('/feeds/posts/default?alt=json&max-results=500')
        .then(function(r){ return r.json(); })
        .then(function(data){
          if(data.feed && data.feed.entry){
            data.feed.entry.forEach(function(e){
              var div = document.createElement('div');
              div.innerHTML = e.content.$t;
              (div.innerText||div.textContent).split('\n').forEach(function(line){
                var parts = line.split(':');
                if(parts.length>=2){
                  var name = parts[0].trim(), secret = parts.slice(1).join(':').trim();
                  if(name && secret) AUTHORIZED_DRIVERS[secret] = name;
                }
              });
            });
          }
        }).catch(function(){});
    }
    loadDrivers();

    function refreshDriversList() {
      showToast('⏳ Fetching latest reps from Blogger...', '#007AFF', 3);
      fetch('/feeds/posts/default?alt=json&max-results=500')
        .then(function(r){ return r.json(); })
        .then(function(data){
          var count = 0;
          AUTHORIZED_DRIVERS = {};
          if(data.feed && data.feed.entry){
            data.feed.entry.forEach(function(e){
              var div = document.createElement('div');
              div.innerHTML = e.content.$t;
              (div.innerText||div.textContent).split('\n').forEach(function(line){
                var parts = line.split(':');
                if(parts.length>=2){
                  var name = parts[0].trim(), secret = parts.slice(1).join(':').trim();
                  if(name && secret) {
                    AUTHORIZED_DRIVERS[secret] = name;
                    count++;
                  }
                }
              });
            });
          }
          if(isAdmin) updateUnscannedUI();
          showToast('✅ Successfully updated! Loaded ' + count + ' reps.', '#34C759', 5);
        }).catch(function(){
          showToast('❌ Failed to update. Please check internet connection.', '#FF3B30', 5);
        });
    }

    /* ═══════════════════════════════════════════════════════
       ONESIGNAL
       ═══════════════════════════════════════════════════════ */
    var oneSignalReady = false;

    window.addEventListener('DOMContentLoaded', function(){
      if(ONESIGNAL_APP_ID === 'YOUR-ONESIGNAL-APP-ID-HERE') {
        setPushStatus('off', 'Push alerts not configured');
        document.getElementById('pushExplainText').textContent = '(Push notifications require OneSignal setup)';
        return;
      }

      window.OneSignalDeferred = window.OneSignalDeferred || [];
      OneSignalDeferred.push(function(OneSignal) {
        OneSignal.init({
          appId: ONESIGNAL_APP_ID,
          allowLocalhostAsSecureOrigin: false,
          notifyButton: { enable: false },
        });

        oneSignalReady = true;

        OneSignal.Notifications.addEventListener('permissionChange', function(granted){
          if(granted) onPushGranted();
          else        setPushStatus('off', 'Notifications blocked');
        });

        OneSignal.Notifications.permission
          ? onPushGranted()
          : setPushStatus('off', 'Tap below to enable alerts');
      });
    });

    function enablePushNotifications() {
      if(!oneSignalReady){ showToast('Push service loading… try again in a moment.','#FF9500'); return; }
      OneSignalDeferred.push(function(OneSignal){
        OneSignal.Notifications.requestPermission().then(function(granted){
          if(granted) onPushGranted();
          else        setPushStatus('off', 'Permission denied — enable in browser settings');
        });
      });
    }

    function onPushGranted() {
      OneSignalDeferred.push(function(OneSignal){
        OneSignal.User.PushSubscription.id
          ? storePlayerId(OneSignal.User.PushSubscription.id)
          : OneSignal.User.PushSubscription.addEventListener('change', function(e){
              if(e.current && e.current.id) storePlayerId(e.current.id);
            });
      });
    }

    function storePlayerId(pid) {
      myOSPlayerId = pid;
      ss('os_player_id_' + (currentDriver.id || 'anon'), pid);
      setPushStatus('on', 'Alerts enabled ✓');
      document.getElementById('pushEnableBtn').style.display = 'none';
      document.getElementById('pushEnabledMsg').style.display = 'block';
      document.getElementById('pushExplainText').style.display = 'none';

      var idx = queue.findIndex(function(q){ return String(q.id) === String(currentDriver.id); });
      if(idx !== -1 && queue[idx].osPlayerId !== pid) {
         queue[idx].osPlayerId = pid;
         syncStateToCloud();
      }
    }

    function setPushStatus(state, text) {
      var dot  = document.getElementById('pushDot');
      var txt  = document.getElementById('pushStatusText');
      var btn  = document.getElementById('pushEnableBtn');
      if(!dot) return;
      dot.className = 'push-dot ' + state;
      if(txt) txt.textContent = text;
      if(state === 'off' && btn) {
        btn.style.display = 'inline-flex';
        document.getElementById('pushEnabledMsg').style.display = 'none';
      }
      if(state === 'on') {
        if(btn) btn.style.display = 'none';
        document.getElementById('pushEnabledMsg').style.display = 'block';
        document.getElementById('pushExplainText').style.display = 'none';
      }
    }

    function sendPushToDriver(playerId, driverName) {
      if(!playerId) return;
      if(ONESIGNAL_REST_KEY === 'YOUR-ONESIGNAL-REST-API-KEY-HERE') return;

      fetch('https://onesignal.com/api/v1/notifications', {
        method: 'POST',
        headers: {
          'Content-Type':  'application/json',
          'Accept': 'application/json',
          'Authorization': 'Basic ' + ONESIGNAL_REST_KEY
        },
        body: JSON.stringify({
          app_id:             ONESIGNAL_APP_ID,
          include_player_ids: [playerId],
          headings:  { en: '🚨 You are Number 1! 🚨' },
          contents:  { en: driverName + ' — You are number one and must take the order immediately.' },

          priority: 10,
          android_visibility: 1,

          ios_sound: 'default',
          android_sound: 'default',
          android_channel_id: '',

          ttl: 300
        })
      }).catch(function(){});
    }

    /* ═══════════════════════════════════════════════════════
       MQTT - DECENTRALIZED CLOUD DATABASE
       ═══════════════════════════════════════════════════════ */
    try {
      mqttClient = mqtt.connect('wss://broker.emqx.io:8084/mqtt', {
        clientId: 'qs_' + Math.random().toString(36).substr(2,10),
        clean: true,
        connectTimeout: 15000,
        reconnectPeriod: 2000,
        keepalive: 30
      });

      mqttClient.on('connect', function(){
        mqttClient.subscribe([TOPIC_SYNC, TOPIC_STATE, TOPIC_PRESENCE], { qos: 1 });
      });

      mqttClient.on('error', function(err) {
        console.warn('MQTT Connection Error:', err);
      });

      mqttClient.on('message', function(topic, message){
        try {
          var data = JSON.parse(message.toString());

          // 🟢 ONLINE PRESENCE TRACKING
          if(topic === TOPIC_PRESENCE && isAdmin && data.id) {
             onlineReps[data.id] = Date.now();
             updateOnlineCount();
             return;
          }

          // ☁️ CLOUD STATE SYNC
          if(topic === TOPIC_STATE) {
             if(data.queue)      { queue = data.queue;             ss('sys_queue', queue); }
             if(data.historyLog) { historyLog = data.historyLog; ss('sys_history', historyLog); }
             if(typeof data.systemActive === 'boolean') {
               systemActive = data.systemActive; ss('sys_active', systemActive);
             }

             if(isAdmin) {
               renderSystemSwitch();
               renderAdminUI();
             } else if(currentDriver.id) {
               var myPos = queue.findIndex(function(x){ return String(x.id) === String(currentDriver.id); });

               if(myPos === 0 && prevMyPos !== 0 && prevMyPos !== -1) {
                 startContinuousRing();
                 showNotifBanner('🔔 أنت الآن رقم 1 — توجّه فوراً!');
                 if(document.hidden && 'Notification' in window && Notification.permission === 'granted') {
                   try{ new Notification('🚨 دورك الآن!', { body: 'أنت رقم 1 — توجّه للاستلام فوراً', icon: 'https://cdn-icons-png.flaticon.com/512/679/679720.png', requireInteraction: true }); }catch(e){}
                 }
               }

               if(prevMyPos >= 0 && myPos === -1){ beginServedCooldown(); }
               prevMyPos = myPos;

               renderRepSystemBanner();
               updateDriverQueueUI(myPos, 'waiting');
               renderDriverQueueUI();
               if(data.historyLog) updateDailyCounter(data.historyLog);
             }
          }

          // Peer-to-Peer PIN & BREAK Verification
          if(topic === TOPIC_SYNC && !isAdmin) {

            // BREAK COMMAND
            if(data.command === 'FORCE_BREAK' && String(currentDriver.id) === String(data.id)) {
              var breakEndTime = Date.now() + data.duration;
              ss('break_until_' + currentDriver.id, breakEndTime);
              autoLeaveQueue();
              showNotifBanner('☕ الإدارة أعطتك فترة راحة لمدة ساعة');
            }

            // PIN IN USE
            if(data.command === 'PIN_CHECK' && currentDriver.id === data.id && data.deviceId !== myDeviceId) {
              mqttClient.publish(TOPIC_SYNC, JSON.stringify({
                command: 'PIN_IN_USE',
                id: data.id,
                targetDevice: data.deviceId
              }), { qos: 1 });
            }
            if(data.command === 'PIN_IN_USE' && data.targetDevice === myDeviceId) {
              clearTimeout(loginTimeout);
              var btn = document.getElementById('loginSubmitBtn');
              if(btn) { btn.textContent = 'Login'; btn.disabled = false; }
              var err = document.getElementById('regError');
              err.textContent = '❌ PIN is currently online on another device.';
              err.style.display = 'block';
            }
          }
        } catch(e){}
      });
    } catch(e){}

    /* ═══════════════════════════════════════════════════════
       NAVIGATION & UI UTILS
       ═══════════════════════════════════════════════════════ */
    function showScreen(id) {
      document.querySelectorAll('.screen').forEach(function(s){ s.classList.remove('active-screen'); });
      document.getElementById(id).classList.add('active-screen');
    }

    function showToast(msg, color, sec) {
      var w = document.getElementById('toast-wrap');
      var t = document.createElement('div');
      t.innerHTML = msg;
      t.style.cssText = 'background:'+(color||'#34C759')+';color:#fff;padding:14px 24px;border-radius:24px;font-size:14px;font-weight:600;box-shadow:0 10px 30px rgba(0,0,0,0.1);max-width:90vw;text-align:center;line-height:1.5; letter-spacing:-0.2px; border:1px solid rgba(0,0,0,0.05);';
      w.appendChild(t);
      var d = (sec||5)*1000;
      setTimeout(function(){ t.style.opacity='0'; t.style.transform='scale(0.9)'; t.style.transition='all .4s ease'; }, d);
      setTimeout(function(){ t.remove(); }, d+500);
    }

    function showNotifBanner(msg) {
      var b = document.getElementById('notif-banner');
      b.textContent = msg;
      b.classList.add('show');
      setTimeout(function(){ b.classList.remove('show'); }, 4500);
    }

    /* PWA */
    var deferredInstall = null;
    window.addEventListener('beforeinstallprompt', function(e){
      e.preventDefault(); deferredInstall = e;
      var btn = document.getElementById('installAppBtn');
      if(btn) btn.style.display = 'inline-flex';
    });
    function promptAppInstall(){
      if(deferredInstall){ deferredInstall.prompt(); deferredInstall.userChoice.then(function(r){ if(r.outcome==='accepted') document.getElementById('installAppBtn').style.display='none'; deferredInstall=null; }); }
      else {
        var ios = /iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.MSStream;
        showToast(ios?'🍎 Tap Share → "Add to Home Screen"':'🤖 Tap browser menu → "Add to Home screen"','#007AFF',7);
      }
    }

    /* ═══════════════════════════════════════════════════════
       AUTH
       ═══════════════════════════════════════════════════════ */
    function verifyAdmin(){
      var pw = document.getElementById('adminPassword');
      if(pw.value === ADMIN_PASSWORD){
        document.getElementById('adminError').style.display = 'none';
        pw.value = ''; isAdmin = true;
        showScreen('dashboardScreen');
        renderSystemSwitch();
        renderAdminUI();
      } else {
        document.getElementById('adminError').style.display = 'block';
        pw.value = ''; pw.focus();
      }
    }
    function logoutAdmin(){ isAdmin=false; document.getElementById('adminSidebar').classList.remove('open'); showScreen('homeScreen'); }

    function openRegScreen(){
      document.getElementById('regError').style.display='none';
      document.getElementById('regSecret').value = sg('saved_rep_secret', '');
      showScreen('driverRegScreen');
    }

    function registerDriver(){
      var secret = document.getElementById('regSecret').value.trim();
      var err = document.getElementById('regError');
      var btn = document.getElementById('loginSubmitBtn');

      if(AUTHORIZED_DRIVERS[secret]){
        err.style.display = 'none';

        if(mqttClient && mqttClient.connected) {
          btn.textContent = 'Verifying...';
          btn.disabled = true;

          mqttClient.publish(TOPIC_SYNC, JSON.stringify({
            command: 'PIN_CHECK',
            id: secret,
            deviceId: myDeviceId
          }), { qos: 1 });

          loginTimeout = setTimeout(function(){
            btn.textContent = 'Login';
            btn.disabled = false;
            executeLogin(secret);
          }, 2000);

        } else {
          executeLogin(secret);
        }
      } else {
        err.textContent = Object.keys(AUTHORIZED_DRIVERS).length===0
          ? '⏳ Still loading — please wait and try again'
          : '❌ Invalid or unregistered code';
        err.style.display = 'block';
        document.getElementById('regSecret').value = '';
        document.getElementById('regSecret').focus();
      }
    }

    function executeLogin(secret) {
      currentDriver = { id: secret, name: AUTHORIZED_DRIVERS[secret] };
      ss('logged_in_driver', currentDriver);
      ss('saved_rep_secret', secret);
      openDriverDashboard();
    }

    function openDriverDashboard(){
      document.getElementById('welcomeDriverText').textContent = 'Welcome, ' + currentDriver.name + ' 👋';
      showScreen('driverCameraScreen');

      var savedPid = sg('os_player_id_' + currentDriver.id, null);
      if(savedPid) myOSPlayerId = savedPid;

      // Restore the post-serve 5-min cooldown so it survives a page refresh / reopen
      restoreServedCooldown();

      var lastPos = sg('last_pos_' + currentDriver.id, -1);
      if(lastPos >= 0) updateDriverQueueUI(lastPos, 'waiting');
      renderDriverQueueUI();
      updateDailyCounter(historyLog);

      if(oneSignalReady){
        OneSignalDeferred.push(function(OS){
          if(OS.Notifications.permission){
            onPushGranted();
          } else {
            OS.Notifications.requestPermission().then(function(granted){
              if(granted) onPushGranted();
              else        setPushStatus('off', 'Tap below to enable alerts');
            });
          }
        });
      } else if('Notification' in window){
        if(Notification.permission === 'granted'){
          setPushStatus('on', 'Alerts enabled ✓');
        } else if(Notification.permission === 'default'){
          Notification.requestPermission().then(function(r){
            if(r === 'granted') setPushStatus('on', 'Alerts enabled ✓');
            else                setPushStatus('off', 'Tap below to enable alerts');
          });
        }
      }

      renderRepSystemBanner();
      requestWakeLock();
      startLocationTracking();
      startNativeBackgroundTracking();

      if(mqttClient && mqttClient.connected) {
         mqttClient.publish(TOPIC_PRESENCE, JSON.stringify({ id: currentDriver.id }), {qos: 0});
      }
    }

    function logoutDriver(){
      stopLocationTracking(); stopContinuousRing();
      servedCooldown=false; servedAt=0; prevMyPos=-1;
      ss('logged_in_driver', null);
      // NOTE: 'saved_rep_secret' is intentionally KEPT so the rep's code stays
      // pre-filled on the login screen next time and is never lost on logout.
      currentDriver = { id:null, name:null }; myOSPlayerId = null;
      var box = document.getElementById('queuePositionBox');
      if(box){ box.textContent='📍 Locating you…'; box.style.background=''; box.style.borderColor=''; }
      openRegScreen();
    }

    window.addEventListener('DOMContentLoaded', function(){
      var s = sg('logged_in_driver',null);
      if(s && s.id){ currentDriver=s; isAdmin=false; openDriverDashboard(); }
      if(window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone){
        var b=document.getElementById('installAppBtn'); if(b) b.style.display='none';
      }
    });

    document.addEventListener('visibilitychange', function(){
      if(!document.hidden && currentDriver.id){
        requestWakeLock();
        if(geoWatchId === null) startLocationTracking();
        quickLocationCheck();
        if(mqttClient && mqttClient.connected) mqttClient.publish(TOPIC_PRESENCE, JSON.stringify({ id: currentDriver.id }), {qos: 0});
      }
    });
    window.addEventListener('focus', function(){
      if(currentDriver.id){ requestWakeLock(); quickLocationCheck(); }
    });

    /* ═══════════════════════════════════════════════════════
       AUDIO
       ═══════════════════════════════════════════════════════ */
    function playSuccessSound(){
      try{
        var ctx=new(window.AudioContext||window.webkitAudioContext)();
        var osc=ctx.createOscillator(),gain=ctx.createGain();
        osc.connect(gain);gain.connect(ctx.destination);
        osc.type='sine'; var now=ctx.currentTime;
        [523.25,659.25,783.99,1046.5].forEach(function(f,i){osc.frequency.setValueAtTime(f,now+i*.1);});
        gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(0.3,now+.05);
        gain.gain.setValueAtTime(0.3,now+.35);gain.gain.linearRampToValueAtTime(0,now+.45);
        osc.start(now);osc.stop(now+.5);
      }catch(e){}
    }

    function triggerRingAlert(){
      try{
        var ctx=new(window.AudioContext||window.webkitAudioContext)();
        var now=ctx.currentTime;
        [0,.6,1.2].forEach(function(off){
          var o=ctx.createOscillator(),g=ctx.createGain();
          o.connect(g);g.connect(ctx.destination);o.type='sine';
          o.frequency.setValueAtTime(880,now+off);o.frequency.setValueAtTime(1108.73,now+off+.1);
          g.gain.setValueAtTime(0,now+off);g.gain.linearRampToValueAtTime(0.5,now+off+.05);
          g.gain.linearRampToValueAtTime(0,now+off+.4);
          o.start(now+off);o.stop(now+off+.5);
        });
        if('vibrate' in navigator) navigator.vibrate([400,200,400,200,400]);
      }catch(e){}
    }

    function startContinuousRing(){
      if(ringInterval) return;
      ringCount=1; triggerRingAlert();
      ringInterval=setInterval(function(){ ringCount++; if(ringCount<=3) triggerRingAlert(); else stopContinuousRing(); },3000);
    }
    function stopContinuousRing(){
      clearInterval(ringInterval); ringInterval=null; ringCount=0;
    }

    /* ═══════════════════════════════════════════════════════
       GEOLOCATION — HAVERSINE + LIVE TRACKER
       ═══════════════════════════════════════════════════════ */
    function haversineDistance(lat1, lng1, lat2, lng2){
      var R = 6371000;
      var dLat = (lat2-lat1)*Math.PI/180, dLng = (lng2-lng1)*Math.PI/180;
      var a = Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLng/2)*Math.sin(dLng/2);
      return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
    }

    function renderTracker(dist, inQueue){
      var box=document.getElementById('liveTracker'), dEl=document.getElementById('ltDistance'), sEl=document.getElementById('ltState');
      if(!box||!dEl||!sEl) return;

      var breakTimeRemaining = getRemainingBreakTime();

      dEl.textContent = dist>=1000 ? (dist/1000).toFixed(2)+' كم' : Math.round(dist)+' م';
      box.classList.remove('in-range','out-range');
      box.style.borderColor = ''; box.style.background = '';

      if(!systemActive){
        box.classList.add('out-range'); sEl.textContent='🔴 النظام متوقف من قبل الإدارة';
      } else if (breakTimeRemaining > 0) {
        var mins = Math.floor(breakTimeRemaining / 60000);
        box.classList.add('out-range');
        box.style.borderColor = 'var(--amber)'; box.style.background = 'rgba(255,149,0,0.1)';
        sEl.textContent = '☕ أنت في فترة راحة. يتبقى: ' + mins + ' دقيقة';
      } else if(dist<=AUTO_JOIN_METERS && servedCooldown){
        var remaining = Math.max(0, 300 - Math.floor((Date.now()-servedAt)/1000));
        var mins = Math.floor(remaining/60), secs = remaining%60;
        box.classList.add('in-range');
        sEl.textContent = '⏳ انتظر ' + mins + ':' + (secs<10?'0':'') + secs + ' دقيقة ثم ستحصل على رقم';
      } else if(dist<=AUTO_JOIN_METERS){
        box.classList.add('in-range'); sEl.textContent=inQueue?'✅ داخل النطاق — لديك رقم في الطابور':'✅ داخل النطاق — جارٍ الحجز…';
      } else {
        box.classList.add('out-range'); sEl.textContent='🚶 اقترب إلى المستودع للحصول على رقم';
      }
    }

    function autoJoinQueue(){
      if(!(mqttClient&&mqttClient.connected)) return;
      if(queue.some(function(d){return String(d.id)===String(currentDriver.id);})) return;
      var t=Date.now();
      queue.push({id:String(currentDriver.id),name:currentDriver.name,time:new Date(t).toLocaleTimeString('en-US'),timestamp:t,osPlayerId:myOSPlayerId||null,status:'waiting'});
      queue.sort(function(a,b){return (a.timestamp||0)-(b.timestamp||0);});
      ss('sys_queue',queue);
      var myPos=queue.findIndex(function(x){return String(x.id)===String(currentDriver.id);});
      prevMyPos=myPos;
      renderDriverQueueUI();
      updateDriverQueueUI(myPos,'waiting');
      syncStateToCloud();
      playSuccessSound();
    }

    function autoLeaveQueue(){
      if(!(mqttClient&&mqttClient.connected)) return;
      if(!queue.some(function(d){return String(d.id)===String(currentDriver.id);})) return;
      queue=queue.filter(function(d){return String(d.id)!==String(currentDriver.id);});
      ss('sys_queue',queue); ss('last_pos_'+currentDriver.id,-1);
      prevMyPos=-1;
      renderDriverQueueUI();
      updateDriverQueueUI(-1,'left');
      syncStateToCloud();
    }

    function startLocationTracking(){
      if(geoWatchId!==null) return;
      var sEl=document.getElementById('ltState');
      if(!navigator.geolocation){ if(sEl) sEl.textContent='⚠️ الجهاز لا يدعم تحديد الموقع'; return; }
      geoWatchId=navigator.geolocation.watchPosition(
        function(pos){
          var dist=haversineDistance(pos.coords.latitude,pos.coords.longitude,TARGET_LAT,TARGET_LNG);
          lastDist=dist;
          if(dist>AUTO_LEAVE_METERS){ clearServedCooldown(); }

          var inQueue=queue.some(function(d){return String(d.id)===String(currentDriver.id);});
          var breakTimeRemaining = getRemainingBreakTime();

          if(dist<=AUTO_JOIN_METERS && !inQueue && systemActive && breakTimeRemaining === 0){
            if(servedCooldown){
              if(servedAt>0 && (Date.now()-servedAt)>=300000){ clearServedCooldown(); autoJoinQueue(); }
            } else { autoJoinQueue(); }
          }

          inQueue=queue.some(function(d){return String(d.id)===String(currentDriver.id);});
          renderTracker(dist,inQueue);
        },
        function(err){
          var sEl=document.getElementById('ltState');
          if(sEl) sEl.textContent=(err&&err.code===1)?'⚠️ فعّل صلاحية الموقع للتطبيق':'⚠️ تعذّر تحديد موقعك — تأكد من تفعيل GPS';
        },
        {enableHighAccuracy:true, timeout:15000, maximumAge:2000}
      );
    }

    function stopLocationTracking(){
      if(geoWatchId!==null){ try{navigator.geolocation.clearWatch(geoWatchId);}catch(e){} geoWatchId=null; }
      releaseWakeLock();
    }

    /* ═══════════════════════════════════════════════════════
       NATIVE (Capacitor) BACKGROUND-LOCATION BRIDGE
       Runs ONLY inside the native Android app (see android-app/). In a normal
       browser window.Capacitor is undefined, so this is a no-op and the web
       app behaves exactly as before. It starts a foreground-service-backed
       watcher that keeps delivering coordinates — and keeps the app process
       (MQTT + queue logic) alive — even when the app is backgrounded or the
       screen is off, so the rep gets a queue number without keeping the app open.
       ═══════════════════════════════════════════════════════ */
    var nativeBgStarted = false;
    function startNativeBackgroundTracking(){
      try{
        if(nativeBgStarted) return;
        if(!(window.Capacitor && typeof Capacitor.isNativePlatform === 'function' && Capacitor.isNativePlatform())) return;
        var BG = Capacitor.Plugins && Capacitor.Plugins.BackgroundGeolocation;
        if(!BG) return;
        nativeBgStarted = true;
        BG.addWatcher({
          backgroundMessage: 'تتبّع موقعك فعّال لإعطائك رقم الطابور تلقائياً',
          backgroundTitle: 'نظام الطابور يعمل',
          requestPermissions: true,
          stale: false,
          distanceFilter: 10
        }, function(location, error){
          if(error || !location) return;
          if(!currentDriver || !currentDriver.id) return;
          var dist = haversineDistance(location.latitude, location.longitude, TARGET_LAT, TARGET_LNG);
          lastDist = dist;
          if(dist > AUTO_LEAVE_METERS){ clearServedCooldown(); }
          var inQueue = queue.some(function(d){return String(d.id)===String(currentDriver.id);});
          var breakTimeRemaining = getRemainingBreakTime();
          if(dist<=AUTO_JOIN_METERS && !inQueue && systemActive && breakTimeRemaining===0){
            if(servedCooldown){
              if(servedAt>0 && (Date.now()-servedAt)>=300000){ clearServedCooldown(); autoJoinQueue(); }
            } else { autoJoinQueue(); }
          }
          inQueue = queue.some(function(d){return String(d.id)===String(currentDriver.id);});
          renderTracker(dist, inQueue);
        }).then(function(id){ window.__bgWatcherId = id; }).catch(function(){ nativeBgStarted = false; });
      }catch(e){}
    }

    // Refresh countdown display every second
    setInterval(function(){
      if(!currentDriver || !currentDriver.id) return;

      var inQueue = queue.some(function(d){return String(d.id)===String(currentDriver.id);});
      var breakTime = getRemainingBreakTime();

      if(breakTime > 0 || (servedCooldown && servedAt)) {
        renderTracker(lastDist, inQueue);
      }

      if(breakTime === 0 && servedCooldown && servedAt && lastDist<=AUTO_JOIN_METERS && (Date.now()-servedAt)>=300000){
        clearServedCooldown(); autoJoinQueue();
      }
    }, 1000);

    function requestWakeLock(){
      try{
        if('wakeLock' in navigator && !wakeLock){
          navigator.wakeLock.request('screen').then(function(wl){
            wakeLock = wl;
            wakeLock.addEventListener('release', function(){ wakeLock = null; });
          }).catch(function(){});
        }
      }catch(e){}
    }
    function releaseWakeLock(){
      try{ if(wakeLock){ wakeLock.release(); wakeLock = null; } }catch(e){}
    }

    function quickLocationCheck(){
      if(!navigator.geolocation || !currentDriver.id) return;
      navigator.geolocation.getCurrentPosition(function(pos){
        var dist=haversineDistance(pos.coords.latitude,pos.coords.longitude,TARGET_LAT,TARGET_LNG);
        lastDist=dist;
        if(dist>AUTO_LEAVE_METERS){ clearServedCooldown(); }

        var inQueue=queue.some(function(d){return String(d.id)===String(currentDriver.id);});
        var breakTimeRemaining = getRemainingBreakTime();

        if(dist<=AUTO_JOIN_METERS && !inQueue && systemActive && breakTimeRemaining === 0){
          if(servedCooldown){
            if(servedAt>0 && (Date.now()-servedAt)>=300000){ clearServedCooldown(); autoJoinQueue(); }
          } else { autoJoinQueue(); }
        }

        inQueue=queue.some(function(d){return String(d.id)===String(currentDriver.id);});
        renderTracker(dist,inQueue);
      }, function(){}, {enableHighAccuracy:true, timeout:10000, maximumAge:0});
    }

    /* ═══════════════════════════════════════════════════════
       QUEUE MANAGEMENT & UI
       ═══════════════════════════════════════════════════════ */
    function updateDriverQueueUI(pos, status){
      ss('last_pos_'+currentDriver.id, pos);
      var box=document.getElementById('queuePositionBox');
      if(!box) return;
      if(pos===0){
        box.innerHTML="You are number <span class='big-number'>1</span><span style='font-size:15px;'>Head to pickup immediately! 🎉</span>";
        box.style.background='rgba(52, 199, 89, 0.1)'; box.style.borderColor='var(--green)';
        startContinuousRing();
      } else if(pos>0){
        stopContinuousRing();
        box.innerHTML="You are number <span class='big-number'>"+(pos+1)+"</span>";
        box.style.background='rgba(0, 122, 255, 0.1)'; box.style.borderColor='var(--teal)';
      } else {
        stopContinuousRing();
        box.innerHTML='📍 اقترب من المستودع للحصول على رقم';
        box.style.background='rgba(0,0,0,0.03)'; box.style.borderColor='rgba(0,0,0,0.1)';
      }
    }

    function renderDriverQueueUI() {
      var container = document.getElementById('driverQueueContainer');
      var tbody = document.getElementById('driverQueueBody');
      if(!container || !tbody) return;

      if(!queue || queue.length === 0) {
        container.style.display = 'none';
        return;
      }

      container.style.display = 'block';
      tbody.innerHTML = '';

      queue.forEach(function(d, i){
        var tr = document.createElement('tr');
        if(String(d.id) === String(currentDriver.id)) {
          tr.style.background = 'rgba(0, 122, 255, 0.1)';
          tr.innerHTML = '<td><strong>' + (i+1) + '</strong></td><td style="color:var(--teal);"><strong>' + esc(d.name) + ' (You)</strong></td>';
        } else {
          tr.innerHTML = '<td><strong>' + (i+1) + '</strong></td><td>' + esc(d.name) + '</td>';
        }
        tbody.appendChild(tr);
      });
    }

    function updateDailyCounter(cloudHistory) {
      var now = new Date();
      var currentDayKey = now.getDate() + '-' + now.getMonth() + '-' + now.getFullYear();

      var record = sg('rep_daily_record_' + currentDriver.id, { day: currentDayKey, countedTimestamps: [], count: 0 });

      if (record.day !== currentDayKey) {
        record = { day: currentDayKey, countedTimestamps: [], count: 0 };
      }

      var hasUpdates = false;
      cloudHistory.forEach(function(item) {
        if (String(item.id) === String(currentDriver.id) && item.completedAt) {
          if (record.countedTimestamps.indexOf(item.completedAt) === -1) {
            var orderDate = new Date(item.completedAt);
            var orderDayKey = orderDate.getDate() + '-' + orderDate.getMonth() + '-' + orderDate.getFullYear();

            if (orderDayKey === currentDayKey) {
              record.countedTimestamps.push(item.completedAt);
              record.count++;
              hasUpdates = true;
            }
          }
        }
      });

      if (hasUpdates || !document.getElementById('daily-count')) {
        ss('rep_daily_record_' + currentDriver.id, record);
      }

      var countEl = document.getElementById('daily-count');
      if (countEl) {
        countEl.textContent = record.count;
      }
    }

    // Orders-completed-today count stays hidden until the rep taps the button
    function toggleDailyCount(){
      var c = document.getElementById('daily-count');
      var b = document.getElementById('toggleCountBtn');
      if(!c) return;
      if(c.style.display === 'none'){ c.style.display=''; if(b) b.textContent='🙈 إخفاء العدد'; }
      else { c.style.display='none'; if(b) b.textContent='👁️ إظهار عدد طلباتي اليوم'; }
    }

    function syncStateToCloud(){
      if(mqttClient && mqttClient.connected){
        var payload = { queue: queue, historyLog: historyLog, systemActive: systemActive };
        mqttClient.publish(TOPIC_STATE, JSON.stringify(payload), {retain: true, qos: 1});
      }
    }

    function removeFromQueue(id){
      var idx=queue.findIndex(function(d){return String(d.id)===String(id);});
      if(idx===-1) return;
      var wasFirst=(idx===0);
      queue.splice(idx,1);
      ss('sys_queue',queue);
      renderAdminUI();
      syncStateToCloud();
      showToast('🗑 تم حذف المندوب من الطابور','var(--amber)');
      if(wasFirst && queue.length>0 && queue[0].osPlayerId){
        sendPushToNewFirst(queue[0].osPlayerId, queue[0].name);
      }
    }

    function sendPushToNewFirst(playerId, driverName){
      if(!playerId) return;
      if(ONESIGNAL_REST_KEY==='YOUR-ONESIGNAL-REST-API-KEY-HERE') return;
      fetch('https://onesignal.com/api/v1/notifications',{
        method:'POST',
        headers:{'Content-Type':'application/json','Accept':'application/json','Authorization':'Basic '+ONESIGNAL_REST_KEY},
        body:JSON.stringify({
          app_id:ONESIGNAL_APP_ID,
          include_player_ids:[playerId],
          headings:{en:'🔔 أنت الآن رقم 1!'},
          contents:{en:driverName+' — أصبحت رقم واحد في الطابور. توجّه فوراً للاستلام!'},
          priority:10, android_visibility:1,
          ios_sound:'default', android_sound:'default', ttl:300
        })
      }).catch(function(){});
    }

    function toggleSystem(){
      systemActive=!systemActive;
      ss('sys_active',systemActive);
      renderSystemSwitch();
      renderAdminUI();
      syncStateToCloud();
      showToast(systemActive?'🟢 تم تشغيل النظام':'🔴 تم إيقاف النظام', systemActive?'var(--green)':'var(--red)');
    }

    function renderSystemSwitch(){
      var box=document.getElementById('systemSwitchBox'), txt=document.getElementById('sswText'), btn=document.getElementById('sswBtn');
      if(!box||!txt||!btn) return;
      box.classList.remove('sys-on','sys-off');
      if(systemActive){ box.classList.add('sys-on'); txt.textContent='النظام يعمل'; btn.textContent='إيقاف النظام'; }
      else             { box.classList.add('sys-off'); txt.textContent='النظام متوقف'; btn.textContent='تشغيل النظام'; }
    }

    function renderRepSystemBanner(){
      var b=document.getElementById('repSystemStoppedBanner');
      if(b) b.style.display=systemActive?'none':'block';
    }

    function renderAdminUI(){
      document.getElementById('stat-waiting').textContent  = queue.length;
      document.getElementById('stat-assigned').textContent = historyLog.length;

      var nextEl=document.getElementById('nextDriver'), btn=document.getElementById('assignBtn');
      if(!systemActive){
        nextEl.textContent='⏸️ النظام متوقف';
        btn.style.display='none';
      } else if(queue.length>0){
        nextEl.textContent='🧑 '+queue[0].name;
        btn.style.display='inline-flex';
      } else {
        nextEl.textContent='No reps waiting'; btn.style.display='none';
      }

      var body=document.getElementById('tableBody'); body.innerHTML='';
      if(queue.length===0){
        body.innerHTML='<tr><td colspan="4" style="text-align:center;color:rgba(0,0,0,0.4);padding:18px;">Queue is empty</td></tr>';
      } else {
        queue.forEach(function(d,i){
          var tr=document.createElement('tr');
          tr.innerHTML='<td><strong>'+(i+1)+'</strong></td><td>'+esc(d.name)+'</td><td>'+esc(d.time)+'</td>'
            +'<td style="display:flex; gap:6px; justify-content:center;">'
            +'<button class="btn-remove" style="background:rgba(255, 149, 0, 0.1); color:var(--amber); border:none;" onclick="giveBreak(\''+esc(String(d.id))+'\')">☕ بريك</button>'
            +'<button class="btn-remove" onclick="removeFromQueue(\''+esc(String(d.id))+'\')">✕ حذف</button></td>';
          body.appendChild(tr);
        });
      }

      var hb=document.getElementById('historyTableBody'); hb.innerHTML='';
      if(historyLog.length===0){
        hb.innerHTML='<tr><td colspan="3" style="text-align:center;color:rgba(0,0,0,0.4);padding:18px;">No completed orders yet</td></tr>';
      } else {
        historyLog.slice().reverse().forEach(function(d,i){
          var tr=document.createElement('tr');
          tr.innerHTML='<td><strong>'+(historyLog.length-i)+'</strong></td><td>'+esc(d.name)+'</td><td>'+esc(d.time)+'</td>';
          hb.appendChild(tr);
        });
      }

      updateUnscannedUI();
    }

    function assignNextOrder(){
      if(!systemActive){ showToast('🔴 النظام متوقف — شغّل النظام أولاً','var(--red)'); return; }
      if(!queue.length) return;

      var done = queue.shift();
      done.time = new Date().toLocaleTimeString('en-US');
      done.completedAt = Date.now();
      historyLog.push(done);
      ss('sys_queue', queue);
      ss('sys_history', historyLog);

      if(done.osPlayerId){
        sendPushToDriver(done.osPlayerId, done.name);
        showToast('✅ Order assigned to ' + done.name + ' — push sent 🔔', 'var(--green)');
      } else {
        showToast('✅ Order assigned to ' + done.name, 'var(--green)');
      }

      if(queue.length>0 && queue[0].osPlayerId){
        sendPushToNewFirst(queue[0].osPlayerId, queue[0].name);
      }

      renderAdminUI();
      syncStateToCloud();
    }

    function clearAllData(){
      if(!confirm('Clear ALL queue and history? This cannot be undone.')) return;
      queue=[]; historyLog=[];
      ss('sys_queue',[]); ss('sys_history',[]);
      renderAdminUI();
      syncStateToCloud();
      showToast('🗑️ All data cleared','#8E8E93');
    }

    /* ═══════════════════════════════════════════════════════
       SIDEBAR & UTILS
       ═══════════════════════════════════════════════════════ */
    function toggleSidebar(){ document.getElementById('adminSidebar').classList.toggle('open'); }

    function updateUnscannedUI(){
      var list=document.getElementById('unscannedList'); if(!list) return;
      list.innerHTML='';
      var activeIds  = queue.map(function(q){ return q.id; });
      var historyIds = historyLog.map(function(h){ return h.id; });
      var count = 0;
      Object.keys(AUTHORIZED_DRIVERS).forEach(function(secret){
        if(activeIds.indexOf(secret)===-1 && historyIds.indexOf(secret)===-1){
          count++;
          var li=document.createElement('li');
          li.innerHTML='<span>'+esc(AUTHORIZED_DRIVERS[secret])+'</span>';
          list.appendChild(li);
        }
      });
      if(count===0) list.innerHTML='<li style="opacity:.5;text-align:center;">All reps are at the warehouse! 🎉</li>';
      var badge=document.getElementById('unscannedBadge'); if(badge) badge.textContent=count;
    }

    function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

    /* ═══════════════════════════════════════════════════════
       PRESENCE SYSTEM (PING & CLEANUP)
       ═══════════════════════════════════════════════════════ */

    setInterval(function() {
      if (mqttClient && mqttClient.connected && currentDriver && currentDriver.id && !isAdmin) {
        mqttClient.publish(TOPIC_PRESENCE, JSON.stringify({ id: currentDriver.id }), {qos: 0});
      }
    }, 10000);

    setInterval(function() {
      if (isAdmin) updateOnlineCount();
    }, 5000);

    function updateOnlineCount() {
      var now = Date.now();
      var count = 0;
      for(var id in onlineReps) {
        if(now - onlineReps[id] < 25000) {
          count++;
        } else {
          delete onlineReps[id];
        }
      }
      var el = document.getElementById('stat-online');
      if(el) el.textContent = count;
    }

    /* ═══════════════════════════════════════════════════════
       DISABLE ZOOM — keep it a fixed, app-like page
       (double-tap zoom handled by CSS touch-action; pinch handled here)
       ═══════════════════════════════════════════════════════ */
    (function(){
      ['gesturestart','gesturechange','gestureend'].forEach(function(ev){
        document.addEventListener(ev, function(e){ e.preventDefault(); }, {passive:false});
      });
      document.addEventListener('touchmove', function(e){
        if(e.touches && e.touches.length > 1){ e.preventDefault(); }
      }, {passive:false});
      document.addEventListener('dblclick', function(e){ e.preventDefault(); }, {passive:false});
      document.addEventListener('wheel', function(e){ if(e.ctrlKey){ e.preventDefault(); } }, {passive:false});
    })();

    //

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
                + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
